cases.judge_raw:
{
  "claims": [
    {
      "claim": "确认手机连接的是2.4GHz Wi-Fi网络。",
      "verdict": "supported",
      "evidence_index": [1, 2],
      "reason": "片段[2]步骤1明确要求确认2.4GHz Wi-Fi，片段[1]也说明配网优先使用2.4GHz网络。"
    },
    {
      "claim": "若为双频合一路由器，建议临时将2.4G与5G频段的Wi-Fi名称分开设置。",
      "verdict": "supported",
      "evidence_index": [1, 2],
      "reason": "片段[1]和[2]均建议双频合一路由临时拆分2.4G/5G名称。"
    },
    {
      "claim": "将机器移至路由器附近。",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]明确说'将机器移至路由器附近'。"
    },
    {
      "claim": "确保信号良好。",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "片段未在配网失败上下文中明确'确保信号良好'，仅提及移至路由器附近；此为目的性表述，缺乏直接依据。"
    },
    {
      "claim": "关闭路由器的AP隔离与访客网络限制。",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]明确建议关闭AP隔离与访客网络限制。"
    },
    {
      "claim": "Wi-Fi名称避免使用特殊符号。",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]明确说'Wi-Fi名称避免特殊符号'。"
    },
    {
      "claim": "长按基站上的召回键与清洗键3秒。",
      "verdict": "supported",
      "evidence_index": [2],
      "reason": "片段[2]步骤2明确说明长按召回键与清洗键3秒。"
    },
    {
      "claim": "听到语音提示或观察指示灯慢闪后，在App中按引导操作。",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "片段[1]提到'指示灯慢闪或语音提示后在App按引导操作'。"
    },
    {
      "claim": "在App中删除旧设备记录。",
      "verdict": "supported",
      "evidence_index": [1, 2],
      "reason": "片段[1]和[2]均提到在App中删除旧设备记录。"
    },
    {
      "claim": "重新扫描水箱盖内侧二维码进行绑定。",
      "verdict": "supported",
      "evidence_index": [2],
      "reason": "片段[2]步骤3明确说重新扫描水箱盖内侧二维码绑定。"
    },
    {
      "claim": "若上述步骤均无效，请停止自助排查并联系官方售后。",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于'请联系售后'类兜底话术，非事实性内容。"
    }
  ]
}
